[round 0 theorist] {
  "hypothesis": "Regime 1 is a USD-driven regime where DX-Y.NYB dominates feature importance (rank 1, importance 0.114). EFA, as the highest-betweenness bridge asset (betweenness 0.333), acts as the primary conduit for dollar shocks between U.S. and international markets. A multivariate Chronos model restricted to only the DX-Y.NYB covariate and ensembled with 30% naive will outperform the full multivariate baseline for EFA by concentrating on the exact macro channel that drives cross-border spillovers, whereas the full model dilutes this signal across irrelevant covariates. SPY (the eigenvector hub) is included as a control to test whether the effect is specific to bridge-asset dynamics.",
  "experiment": {
    "type": "spawn_method",
    "params": {
      "spec": {
        "name": "efa_dxy_bridge_focus",
        "base": "chronos2_multivariate",
        "covariate_subset": [
          "DX-Y.NYB"
        ],
        "ensemble_naive_weight": 0.3,
        "max_windows": 8,
        "asset_subset": [
          "EFA",
          "SPY"
        ]
      }
    }
  },
  "proposer_role": "theorist"
}

